/**
 * Canonical object-path conventions inside the private `nuri-product-images`
 * bucket. These MUST match the storefront so that dashboard uploads are picked
 * up automatically by the public website.
 *
 *   products/{productId}/image.{ext}    product image
 *
 * Product ids are UUIDs generated by the database, so a product must exist
 * before its image can be uploaded (create → then upload/replace on the edit page).
 */

export function normalizeExt(extension: string): string {
  return extension.replace(/^\./, "").toLowerCase();
}

/** Derive a safe, single-segment extension from a filename (default `bin`). */
export function extensionFromFilename(filename: string, fallback = "bin"): string {
  const clean = filename.split(/[?#]/)[0] ?? "";
  const dot = clean.lastIndexOf(".");
  if (dot <= 0 || dot === clean.length - 1) return fallback;
  const ext = normalizeExt(clean.slice(dot + 1));
  return /^[a-z0-9]{1,8}$/.test(ext) ? ext : fallback;
}

export function buildProductImagePath(productId: string, extension = "webp"): string {
  return `products/${productId}/image.${normalizeExt(extension)}`;
}

export function productFolder(productId: string): string {
  return `products/${productId}`;
}

/** True when `path` is the canonical image path for `productId`. */
export function isProductImagePath(productId: string, path: string): boolean {
  return path.startsWith(`products/${productId}/image.`);
}
